"""`Eyewhite card`: generated by export_nodes.py from face_cards.blend; kept by hand from then on."""

NAME = 'Eyewhite card'


def build(lib):
    t = lib.new_material(NAME, props={
            'use_transparency_overlap': False,
            'show_transparent_back': False,
        })

    t.node('ShaderNodeOutputMaterial', 'Material Output', props={
        'location': (822.38525, 8.689714),
    })
    t.node('ShaderNodeTexImage', 'tex.eye_white_mask', props={
        'location': (111.66373, -124.98596),
        'label': 'tex.eye_white_mask',
        'image': lib.image('Eye_White_Alpha'),
        'extension': 'CLIP',
    })
    t.node('ShaderNodeGroup', 'Group', props={
        'node_tree': lib.group('.eyewhite sticker'),
        'location': (468.0395, 1.7242885),
        'width': 251.44336,
    })
    t.node('ShaderNodeTexImage', 'tex.eye_white', props={
        'location': (111.66373, 175.01404),
        'label': 'tex.eye_white',
        'show_texture': True,
    })

    t.link('tex.eye_white_mask', 'Color', 'Group', 2)
    t.link('Group', 'Shader', 'Material Output', 'Surface')
    t.link('tex.eye_white', 'Color', 'Group', 0)
    t.link('tex.eye_white', 'Alpha', 'Group', 'Alpha')
    return t
